// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        bool a = c.supportsInterface(interfaceId);
        bool erc165 = c.supportsInterface(type(IERC165).interfaceId);
        // Universal rule: the contract reports support for any queried interface id,
        // or at minimum always reports ERC165 support. The mutant removes the
        // ERC165 disjunct, so for ids other than IAccessControl's it fails.
        assertTrue(a || erc165);
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
